export interface Def {
    readonly type: string;
}
export interface Internals<Output = unknown> {
    readonly def: Def;
    readonly output: Output;
}
/** The bound is an instantiation with defaults: `Internals<unknown>`. */
export interface Schema<I extends Internals = Internals> {
    readonly def: I["def"];
    clone(def?: I["def"]): Schema<I>;
}
export interface Wrapped<I extends Internals = Internals> extends Schema<I> {}
